package movie.tests;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.view.accessibility.*;import android.widget.*;import android.graphics.Bitmap;import android.database.Cursor;import org.json.*;import java.util.*;import java.io.*;
import com.mgs.carparking.modern.profiles.*;import com.mgs.carparking.modern.catalog.*;import com.mgs.carparking.modern.core.*;
public final class Checks extends Instrumentation {
 private volatile Activity current;private Bundle arguments;private final JSONArray records=new JSONArray();
 public void onCreate(Bundle b){arguments=b;super.onCreate(b);start();}
 public void callActivityOnResume(Activity a){super.callActivityOnResume(a);current=a;}
 private void check(boolean value,String name)throws Exception{if(!value)throw new AssertionError(name);records.put(name);Bundle b=new Bundle();b.putString("check",name);sendStatus(0,b);}
 private void sleep(long ms){SystemClock.sleep(ms);}
 private void main(Runnable r){RuntimeException[] error={null};runOnMainSync(()->{try{r.run();}catch(RuntimeException e){error[0]=e;}});if(error[0]!=null)throw error[0];}
 private void screen(String name)throws Exception{Bitmap b=getUiAutomation().takeScreenshot();File dir=new File(getTargetContext().getExternalFilesDir(null),"checks");dir.mkdirs();try(OutputStream o=new FileOutputStream(new File(dir,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,o);}b.recycle();}
 private AccessibilityNodeInfo node(AccessibilityNodeInfo root,String value){if(root==null)return null;CharSequence text=root.getText(),description=root.getContentDescription();if((text!=null&&text.toString().toLowerCase(Locale.ROOT).contains(value.toLowerCase(Locale.ROOT)))||(description!=null&&description.toString().equalsIgnoreCase(value)))return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo n=node(root.getChild(i),value);if(n!=null)return n;}return null;}
 private boolean exists(String value){return node(getUiAutomation().getRootInActiveWindow(),value)!=null;}
 private void click(String value)throws Exception{AccessibilityNodeInfo n=node(getUiAutomation().getRootInActiveWindow(),value);if(n==null)throw new AssertionError("UI missing: "+value);while(n!=null&&!n.isClickable())n=n.getParent();if(n==null||!n.performAction(AccessibilityNodeInfo.ACTION_CLICK))throw new AssertionError("Click failed: "+value);sleep(350);}
 private AccessibilityNodeInfo scrollable(AccessibilityNodeInfo root){if(root==null)return null;if(root.isScrollable())return root;for(int i=0;i<root.getChildCount();i++){AccessibilityNodeInfo n=scrollable(root.getChild(i));if(n!=null)return n;}return null;}
 private void reveal(String value)throws Exception{for(int i=0;i<8&&!exists(value);i++){AccessibilityNodeInfo list=scrollable(getUiAutomation().getRootInActiveWindow());if(list==null)break;list.performAction(AccessibilityNodeInfo.ACTION_SCROLL_FORWARD);sleep(400);}await(value,3);}
 private void await(String value,int seconds)throws Exception{for(int i=0;i<seconds*2&&!exists(value);i++)sleep(500);check(exists(value),"UI: "+value);}
 private void startActivity(String cls){startActivitySync(new Intent().setClassName(getTargetContext(),cls).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));sleep(700);}
 private Object exo(){return Legacy.call(Legacy.field(current,"f"),"D");}
 private int state(){int[] v={0};main(()->v[0]=((Number)Legacy.call(exo(),"getPlaybackState")).intValue());return v[0];}
 private long position(){long[] v={0};main(()->v[0]=((Number)Legacy.call(exo(),"getCurrentPosition")).longValue());return v[0];}
 private void playerReady()throws Exception{for(int i=0;i<90;i++){sleep(500);if(current.getClass().getName().endsWith("VideoPlayDetailActivity")){try{if(state()==3){check(true,"Real player STATE_READY");return;}}catch(Exception ignored){}}}throw new AssertionError("Real playback not ready; activity="+current.getClass().getName());}
 private void core()throws Exception{
  Context c=getTargetContext();startActivity("com.mgs.carparking.ui.login.splash.SplashActivity");for(int i=0;i<60&&!exists("DESTAQUE NO MOVIE")&&!exists("Quem vai assistir?");i++)sleep(500);if(exists("Quem vai assistir?")){if(exists("Alice"))click("Perfil: Alice");else click("Perfil: Você");}await("DESTAQUE NO MOVIE",30);main(()->Catalog.bootstrap(c));Profiles p=Profiles.get(c);Profiles.Profile old=p.active();p.putProfile("default","Alice",old.avatar,new JSONObject());p.select("default");
  for(Profiles.Profile x:p.all())if(x.name.equals("Bruno")||x.name.equals("Bob"))p.delete(x.id);String temp=p.create("Disposable");p.delete(temp);check(p.all().stream().noneMatch(x->x.id.equals(temp)),"Delete local profile");String bob=p.create("Bob");p.putProfile(bob,"Bruno","",new JSONObject());check(p.all().size()>=2,"Create and edit local profiles");
  p.preference("speed",1.25);p.preference("autoplay_next",false);p.search("Loki");List<Movie> results=Catalog.search("Loki",1);check(!results.isEmpty(),"Real catalog search Loki");
  List<Movie> grouped=Catalog.enrichSeries(results);check(grouped.size()<=results.size(),"Catalog explicit series enrichment");
  Movie loki=grouped.get(0);Movie detail=Catalog.details(loki.id);check(detail.id==loki.id&&!detail.episodes.isEmpty(),"Real authenticated details and episodes");
  Bundle ids=new Bundle();ids.putString("catalog", "search="+results.size()+" grouped="+grouped.size()+" realId="+detail.id+" seasons="+detail.seasons.size()+" episodes="+detail.episodes.size());sendStatus(0,ids);
  if(!p.isSaved(detail.id))p.toggleSaved(detail);check(p.isSaved(detail.id),"Alice list saved");Movie m=Movie.parse(detail.json());m.episode=0;m.position=420000;m.duration=1800000;p.saveProgress(p.activeId(),m);p.flush();p.putProfile("default","Alice",p.active().avatar,p.active().preferences);check(p.progress(m.id)!=null&&p.isSaved(m.id),"Rename preserves progress and list");
  p.select(bob);check(p.searches().isEmpty()&&p.saved().isEmpty()&&p.history(false).isEmpty()&&p.decimal("speed",1)==1&&p.flag("autoplay_next",true),"Profiles isolate history list searches and settings");
  check(Profiles.legacyDatabase("social_video_FREE.db").startsWith("profile_"+bob+"_"),"Legacy database namespace per profile");p.search("Avatar");p.preference("speed",.75);p.select("default");check(p.searches().contains("Loki")&&p.decimal("speed",1)==1.25f&&!p.flag("autoplay_next",true),"Alice preferences restored after switching");
  Object shared=Legacy.call(Legacy.type("com.mgs.carparking.db.DBHelper"),"getDownloadsInstance");p.select(bob);check(shared==Legacy.call(Legacy.type("com.mgs.carparking.db.DBHelper"),"getDownloadsInstance"),"Downloads keep shared helper while profiles switch");p.select("default");byte[] backup=Backup.exportData(c);JSONObject json=new JSONObject(new String(backup,"UTF-8"));check(json.getJSONArray("profiles").length()>=2&&!new String(backup,"UTF-8").contains("device_id"),"Backup contains profiles without service credentials");
  String before=new String(Backup.exportData(c),"UTF-8");boolean rejected=false;try{Backup.restoreData(c,"{\"format\":\"wrong\",\"version\":1}".getBytes("UTF-8"));}catch(Exception e){rejected=true;}check(rejected&&before.equals(new String(Backup.exportData(c),"UTF-8")),"Invalid backup rejected without mutation");
  check(Backup.restoreData(c,backup)>=2&&p.progress(m.id).position==420000&&p.isSaved(m.id),"Backup round trip preserves profile data");
  startActivity("com.mgs.carparking.modern.home.HomeActivity");await("DESTAQUE NO MOVIE",30);screen("home");
  main(()->Routes.details(current,detail));await("Detalhes",10);sleep(2000);screen("details");
  main(()->Routes.play(current,detail,0));playerReady();sleep(2500);if(!exists("Pausar"))click("Controles de reprodução Movie");click("Pausar");check(!Boolean.TRUE.equals(Legacy.call(exo(),"getPlayWhenReady")),"Center pause button");click("Reproduzir");check(Boolean.TRUE.equals(Legacy.call(exo(),"getPlayWhenReady")),"Center play button");click("Pausar");screen("player-video");sleep(250);
  main(()->Legacy.seek(exo(),420000L));sleep(1000);check(position()>=419000,"Seek beyond former free scrub threshold");
  click("Controles de reprodução Movie");if(!exists("Avançar 10 segundos"))click("Controles de reprodução Movie");screen("player");long pos=position();click("Avançar 10 segundos");check(position()>=pos+9000,"Player forward 10 seconds");click("Voltar 10 segundos");check(Math.abs(position()-pos)<1500,"Player rewind 10 seconds");
  click("Bloquear controles");check(!exists("Pausar")&&!exists("Reproduzir"),"Player lock hides playback actions");click("Desbloquear controles");
  click("Velocidade (");await("Velocidade de reprodução",3);click("1,5×");check(p.decimal("speed",1)==1.5f,"Player speed stored per profile");
  click("Episódios");await("Fechar",3);screen("episode-picker");click("2 · 2");sleep(1500);playerReady();check(((Number)Legacy.field(current,"A")).intValue()==1,"Select episode using original engine");if(!exists("Próx. episódio"))click("Controles de reprodução Movie");click("Próx. episódio");sleep(1500);playerReady();check(((Number)Legacy.field(current,"A")).intValue()==2,"Manual next works with autoplay disabled");
  if(!exists("Idioma e legendas"))click("Controles de reprodução Movie");click("Idioma e legendas");sleep(500);screen("track-picker");check(((PopupWindow)Legacy.field(current,"m")).isShowing()&&exists("Áudio")&&exists("Legendas"),"Existing audio subtitle picker accessible");sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);sleep(500);
  if(!exists("Avançar 10 segundos"))click("Controles de reprodução Movie");AccessibilityNodeInfo brightness=node(getUiAutomation().getRootInActiveWindow(),"Brilho da reprodução");Bundle bright=new Bundle();bright.putFloat(AccessibilityNodeInfo.ACTION_ARGUMENT_PROGRESS_VALUE,70);check(brightness!=null&&brightness.performAction(AccessibilityNodeInfo.AccessibilityAction.ACTION_SET_PROGRESS.getId(),bright),"Brightness slider accepts explicit adjustment");sleep(300);check(Math.abs(current.getWindow().getAttributes().screenBrightness-.7f)<.02f,"Brightness affects playback window");sleep(5500);check(!exists("Avançar 10 segundos"),"Controls automatically hide");click("Controles de reprodução Movie");check(exists("Avançar 10 segundos"),"Tap restores controls");
  main(()->Legacy.seek(exo(),420000L));sleep(1000);main(()->com.mgs.carparking.modern.player.PlayerUi.pause(current));p.flush();long saved=p.progress(detail.id).position;check(saved>400000,"Player persists real position");main(()->current.finish());sleep(1000);
  startActivity("com.mgs.carparking.modern.profiles.ProfilesActivity");await("Quem vai assistir?",10);screen("profiles");click("Perfil: Bruno");await("DESTAQUE NO MOVIE",15);check(p.active().name.equals("Bruno")&&p.progress(detail.id)==null,"Profile selection UI switches isolated state");
  main(()->Routes.play(current,detail,0));playerReady();sleep(1000);check(position()<30000,"Second profile starts without Alice progress");main(()->Legacy.seek(exo(),100000L));sleep(1000);main(()->current.finish());sleep(700);startActivity("com.mgs.carparking.modern.profiles.ProfilesActivity");click("Perfil: Alice");await("DESTAQUE NO MOVIE",15);
  main(()->Routes.play(current,detail));playerReady();sleep(1000);check(((Number)Legacy.field(current,"A")).intValue()==2,"Resume correct episode for Alice");check(Math.abs(position()-saved)<15000,"Resume real playback after leaving player");
  if(!exists("Mais opções"))click("Controles de reprodução Movie");click("Mais opções");click("Baixar episódios");sleep(500);PopupWindow picker=null;for(String field:new String[]{"s","t","u"}){Object value=Legacy.field(current,field);if(value instanceof PopupWindow&&((PopupWindow)value).isShowing())picker=(PopupWindow)value;}check(picker!=null,"Original download selector opens");final PopupWindow selected=picker;boolean[] shown={false};main(()->{android.graphics.Rect rect=new android.graphics.Rect();android.graphics.Point real=new android.graphics.Point();current.getWindowManager().getDefaultDisplay().getRealSize(real);shown[0]=selected.getContentView().getGlobalVisibleRect(rect)&&rect.width()>0&&rect.height()>0&&rect.top>=0&&rect.bottom<=real.y;Bundle geometry=new Bundle();geometry.putString("download_viewport",rect.toShortString()+" / "+real.x+"x"+real.y);sendStatus(0,geometry);});check(shown[0],"Download selector stays inside fullscreen viewport");screen("download-selector");sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);sleep(350);check(!selected.isShowing(),"Back closes download selector");
  if(!exists("Mais opções"))click("Controles de reprodução Movie");click("Mais opções");click("Transmitir para TV");sleep(700);screen("cast-selector");Object cast=Legacy.field(current,"N0");check(cast instanceof PopupWindow&&((PopupWindow)cast).isShowing(),"Original cast discovery dialog opens");sendKeyDownUpSync(android.view.KeyEvent.KEYCODE_BACK);sleep(350);
  main(()->current.finish());sleep(700);
  startActivity("com.mgs.carparking.modern.settings.SettingsActivity");reveal("Exportar perfis");screen("settings");
 }
 public void onStart(){Bundle result=new Bundle();try{core();result.putString("result","PASS");result.putString("checks",records.toString());finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("result","FAIL: "+e);result.putString("checks",records.toString());try{screen("failure");}catch(Exception ignored){}finish(Activity.RESULT_CANCELED,result);}}
}
